class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        for m in range(1, n + 1):
            ops, run = 0, 1
            for i in range(1, n):
                if s[i] == s[i - 1]:
                    run += 1
                else:
                    ops += run // (m + 1)
                    run = 1
            ops += run // (m + 1)
            if ops <= numOps:
                return m
        return n

