class Solution {
public:
    int minLength(string s, int numOps) {
        int n = s.size();
        for (int m = 1; m <= n; m++) {
            long long ops = 0;
            int run = 1;
            for (int i = 1; i < n; i++) {
                if (s[i] == s[i - 1]) run++;
                else { ops += run / (m + 1); run = 1; }
            }
            ops += run / (m + 1);
            if (ops <= numOps) return m;
        }
        return n;
    }
};

